int main() {
    int zahl = 3;

    std::cout << "Start" << std::endl;

    if (zahl > 2) {
        std::cout << "Die Zahl " << zahl << " ist groesser als 2" << std::endl;
    }

    for (int i = 1; i <= 3; ++i) {
        std::cout << "Durchlauf " << i << std::endl;
    }

    std::cout << "Ende" << std::endl;
    return 0;
}

