#include <iostream>
#include <string>
#include <vector>

void begruesse(const std::string& wen) {
    std::cout << "Hallo " << wen << "!" << std::endl;
}

int main() {
    std::vector<std::string> namen = {"Anna", "Ben", "Clara"};

    for (const auto& n : namen) {
        begruesse(n);
    }

    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string name = "Anna";
    int alter = 25;
    double groesse = 1.72;
    bool mag_cpp = true;

    std::cout << "Name: " << name << std::endl;
    std::cout << "Alter: " << alter << std::endl;
    std::cout << "Groesse: " << groesse << " m" << std::endl;
    std::cout << "Mag C++: " << mag_cpp << std::endl;

    return 0;
}
